import {uppercutFrame} from './uppercuts.js';
const $=id=>document.getElementById(id),poseNames=['Anticipation','Load','Rise','Contact','Follow-through','Recovery'];
let roster=[],atlas={},selected=0,active=null,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,mirror=false,speed=1,elapsed=0,last=0,request=0,tourTime=0,manualFrame=0;
const cache=new Map();
function image(src){if(!cache.has(src))cache.set(src,new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Could not load '+src));img.src=src;}));return cache.get(src);}
function paint(canvas,entry,img,index,face=1,height=385){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);if(!img)return;const f=entry.frames[index],scale=height/entry.referenceHeight;ctx.save();ctx.translate(canvas.width/2,canvas.height*.92);ctx.scale(face,1);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(img,f.x,f.y,f.w,f.h,-f.anchorX*scale,-f.anchorY*scale,f.w*scale,f.h*scale);ctx.restore();}
function render(index){if(!active)return;paint($('animated'),active.entry,active.image,index,mirror?-1:1);$('phase').textContent=`${index+1} / 6 · ${poseNames[index]}`;document.querySelectorAll('.pose').forEach((b,i)=>b.classList.toggle('active',i===index));}
async function choose(index){const token=++request;selected=(index+roster.length)%roster.length;const f=roster[selected];$('fighter').value=f.id;$('name').textContent=f.name;$('count').textContent=`${selected+1} / ${roster.length}`;$('status').textContent='Loading animation…';elapsed=0;tourTime=0;active=null;try{const entry=atlas[f.id+'Uppercut'];const [art,reference]=await Promise.all([image('./'+entry.src),image('./assets/uppercuts/references/'+f.id+'.webp')]);if(token!==request)return;active={entry,image:art};const ctx=$('original').getContext('2d');ctx.clearRect(0,0,500,550);const scale=385/420;ctx.drawImage(reference,250-256*scale,506-472*scale,512*scale,512*scale);$('status').textContent='';$('strip').replaceChildren(...entry.frames.map((_,i)=>{const b=document.createElement('button');b.className='pose';b.setAttribute('aria-label',poseNames[i]);const c=document.createElement('canvas');c.width=256;c.height=288;b.append(c);const label=document.createElement('span');label.textContent=`${i+1}. ${poseNames[i]}`;b.append(label);paint(c,entry,art,i,mirror?-1:1,215);b.onclick=()=>{playing=false;manualFrame=i;$('pause').textContent='Play';render(i);};return b;}));render(playing?5:manualFrame);}catch(e){$('status').textContent=e.message;}}
$('prev').onclick=()=>choose(selected-1);$('next').onclick=()=>choose(selected+1);$('fighter').onchange=()=>choose(roster.findIndex(f=>f.id===$('fighter').value));$('pause').onclick=()=>{playing=!playing;$('pause').textContent=playing?'Pause':'Play';};$('mirror').onclick=()=>{mirror=!mirror;$('mirror').textContent=mirror?'Face right':'Face left';choose(selected);};$('speed').oninput=()=>{speed=Number($('speed').value);$('speedLabel').textContent=speed+'×';};
function loop(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;if(playing){elapsed+=dt*speed;tourTime+=dt;const cycle=elapsed%1.65;render(cycle<.4?5:cycle<1.12?uppercutFrame((cycle-.4)/.72):5);if($('tour').checked&&tourTime>4.8)choose(selected+1);}requestAnimationFrame(loop);}
try{[roster,atlas]=await Promise.all(['./assets/uppercuts/roster.json','./assets/uppercuts/atlas.json'].map(async src=>{const r=await fetch(src);if(!r.ok)throw Error('Could not load fighter list');return r.json();}));$('fighter').replaceChildren(...roster.map(f=>{const o=document.createElement('option');o.value=f.id;o.textContent=f.name;return o;}));$('pause').textContent=playing?'Pause':'Play';await choose(0);requestAnimationFrame(loop);}catch(e){$('status').textContent=e.message;}
